create extension if not exists pgcrypto;
create schema if not exists legal;

create table if not exists legal.profiles (user_id uuid primary key references auth.users(id) on delete cascade, full_name text not null, role text not null check (role in ('partner','advocate','clerk','finance','administrator','client')), active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists legal.clients (id uuid primary key default gen_random_uuid(), client_number text not null unique, client_type text not null, legal_name text not null, phone text, email text, address text, notes text, status text not null default 'active', created_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists legal.matters (id uuid primary key default gen_random_uuid(), matter_number text not null unique, title text not null, client_id uuid not null references legal.clients(id), practice_area text not null, matter_type text, status text not null default 'intake', confidentiality text not null default 'restricted', description text, opened_at date, closed_at date, created_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists legal.matter_members (matter_id uuid not null references legal.matters(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, assignment_role text not null, created_at timestamptz not null default now(), primary key (matter_id,user_id));
create table if not exists legal.parties (id uuid primary key default gen_random_uuid(), matter_id uuid not null references legal.matters(id) on delete cascade, name text not null, party_type text not null, contact text, notes text, created_at timestamptz not null default now());
create table if not exists legal.tasks (id uuid primary key default gen_random_uuid(), matter_id uuid references legal.matters(id) on delete cascade, title text not null, description text, assigned_to uuid references auth.users(id), status text not null default 'open', priority text not null default 'normal', due_at timestamptz, completed_at timestamptz, created_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists legal.deadlines (id uuid primary key default gen_random_uuid(), matter_id uuid not null references legal.matters(id) on delete cascade, title text not null, deadline_at timestamptz not null, source text, status text not null default 'open', owner_id uuid references auth.users(id), notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists legal.documents (id uuid primary key default gen_random_uuid(), matter_id uuid not null references legal.matters(id) on delete cascade, title text not null, document_type text not null, storage_path text, mime_type text, version integer not null default 1, checksum text, uploaded_by uuid references auth.users(id), created_at timestamptz not null default now());
create table if not exists legal.evidence (id uuid primary key default gen_random_uuid(), matter_id uuid not null references legal.matters(id) on delete cascade, reference text not null, description text not null, source text, storage_path text, exhibit_number text, collected_at timestamptz, recorded_by uuid references auth.users(id), created_at timestamptz not null default now());
create table if not exists legal.invoices (id uuid primary key default gen_random_uuid(), matter_id uuid not null references legal.matters(id) on delete cascade, invoice_number text not null unique, amount numeric(14,2) not null check (amount >= 0), currency text not null default 'UGX', status text not null default 'draft', due_date date, issued_at timestamptz, created_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists legal.payments (id uuid primary key default gen_random_uuid(), invoice_id uuid not null references legal.invoices(id) on delete cascade, amount numeric(14,2) not null check (amount > 0), currency text not null default 'UGX', method text, reference text, paid_at timestamptz not null default now(), recorded_by uuid references auth.users(id), created_at timestamptz not null default now());
create table if not exists legal.audit_events (id uuid primary key default gen_random_uuid(), actor_id uuid references auth.users(id), matter_id uuid references legal.matters(id) on delete set null, action text not null, entity_type text not null, entity_id text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists legal_matters_client_idx on legal.matters(client_id);
create index if not exists legal_members_user_idx on legal.matter_members(user_id);
create index if not exists legal_tasks_matter_idx on legal.tasks(matter_id);
create index if not exists legal_deadlines_matter_idx on legal.deadlines(matter_id);
create index if not exists legal_documents_matter_idx on legal.documents(matter_id);
create index if not exists legal_evidence_matter_idx on legal.evidence(matter_id);
create index if not exists legal_invoices_matter_idx on legal.invoices(matter_id);
create index if not exists legal_audit_matter_idx on legal.audit_events(matter_id);
create or replace function legal.is_staff() returns boolean language sql stable security definer set search_path=legal,public as $$ select exists(select 1 from legal.profiles p where p.user_id=(select auth.uid()) and p.active and p.role <> 'client') $$;
create or replace function legal.is_manager() returns boolean language sql stable security definer set search_path=legal,public as $$ select exists(select 1 from legal.profiles p where p.user_id=(select auth.uid()) and p.active and p.role in ('partner','administrator')) $$;
create or replace function legal.has_matter_access(p_matter uuid) returns boolean language sql stable security definer set search_path=legal,public as $$ select legal.is_manager() or exists(select 1 from legal.matter_members mm join legal.profiles p on p.user_id=mm.user_id where mm.matter_id=p_matter and mm.user_id=(select auth.uid()) and p.active) $$;
alter table legal.profiles enable row level security; alter table legal.clients enable row level security; alter table legal.matters enable row level security; alter table legal.matter_members enable row level security; alter table legal.parties enable row level security; alter table legal.tasks enable row level security; alter table legal.deadlines enable row level security; alter table legal.documents enable row level security; alter table legal.evidence enable row level security; alter table legal.invoices enable row level security; alter table legal.payments enable row level security; alter table legal.audit_events enable row level security;
create policy profiles_self on legal.profiles for select to authenticated using ((select auth.uid())=user_id or legal.is_manager());
create policy clients_staff on legal.clients for all to authenticated using (legal.is_staff()) with check (legal.is_staff());
create policy matters_access on legal.matters for select to authenticated using (legal.has_matter_access(id));
create policy matters_manager_write on legal.matters for all to authenticated using (legal.is_manager()) with check (legal.is_manager());
create policy members_access on legal.matter_members for select to authenticated using (legal.has_matter_access(matter_id));
create policy members_manager_insert on legal.matter_members for insert to authenticated with check (legal.is_manager());
create policy members_manager_update on legal.matter_members for update to authenticated using (legal.is_manager()) with check (legal.is_manager());
create policy members_manager_delete on legal.matter_members for delete to authenticated using (legal.is_manager());
create policy parties_access on legal.parties for all to authenticated using (legal.has_matter_access(matter_id)) with check (legal.has_matter_access(matter_id));
create policy tasks_access on legal.tasks for all to authenticated using (matter_id is null or legal.has_matter_access(matter_id)) with check (matter_id is null or legal.has_matter_access(matter_id));
create policy deadlines_access on legal.deadlines for all to authenticated using (legal.has_matter_access(matter_id)) with check (legal.has_matter_access(matter_id));
create policy documents_access on legal.documents for all to authenticated using (legal.has_matter_access(matter_id)) with check (legal.has_matter_access(matter_id));
create policy evidence_access on legal.evidence for all to authenticated using (legal.has_matter_access(matter_id)) with check (legal.has_matter_access(matter_id));
create policy invoices_access on legal.invoices for all to authenticated using (legal.has_matter_access(matter_id)) with check (legal.has_matter_access(matter_id));
create policy payments_access on legal.payments for all to authenticated using (legal.has_matter_access((select i.matter_id from legal.invoices i where i.id=invoice_id))) with check (legal.has_matter_access((select i.matter_id from legal.invoices i where i.id=invoice_id)));
create policy audit_access on legal.audit_events for select to authenticated using (matter_id is null or legal.has_matter_access(matter_id));
revoke all on schema legal from anon; grant usage on schema legal to authenticated;